def uniform_rects(g,minh=1,minw=1):
 R,C=len(g),len(g[0]); rects=set()
 for top in range(R):
  for bot in range(top+minh-1,R):
   vals=[]
   for c in range(C):
    v=g[top][c]
    vals.append(v if all(g[r][c]==v for r in range(top,bot+1)) else None)
   c=0
   while c<C:
    v=vals[c]
    if v is None: c+=1; continue
    e=c+1
    while e<C and vals[e]==v: e+=1
    if e-c>=minw: rects.add((top,c,bot,e-1,v))
    c=e
 # filter rectangles which can expand into another candidate
 maxs=[]
 for a in rects:
  r0,c0,r1,c1,v=a
  if not any(b!=a and b[4]==v and b[0]<=r0 and b[1]<=c0 and b[2]>=r1 and b[3]>=c1 for b in rects): maxs.append(a)
 return sorted(maxs)
